package com.rentalproperty.servlet;
import com.rentalproperty.model.RentalRequest; import com.rentalproperty.util.DBConnection; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet("/requests") public class RequestManagementServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{HttpSession s=req.getSession(false);if(s==null||s.getAttribute("userId")==null){res.sendRedirect("login.jsp");return;}List<RentalRequest> list=new ArrayList<RentalRequest>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT r.*,p.title FROM rental_requests r JOIN properties p ON r.property_id=p.property_id WHERE p.owner_id=? ORDER BY r.request_id DESC")){p.setInt(1,(Integer)s.getAttribute("userId"));ResultSet r=p.executeQuery();while(r.next())list.add(new RentalRequest(r.getInt("request_id"),r.getString("title"),r.getString("tenant_name"),r.getString("phone"),r.getDate("request_date"),r.getString("status")));}catch(Exception e){throw new ServletException(e);}req.setAttribute("requests",list);req.getRequestDispatcher("requests.jsp").forward(req,res);}
}
